body.script:
(async function () {
  const status = document.getElementById('godly-status');
  const splash = document.getElementById('godly-splash');
  const frame = document.getElementById('godly-viewport');

  function dismissSplash() {
    if (splash) {
      splash.style.opacity = '0';
      setTimeout(() => { splash.style.display = 'none'; }, 500);
    }
  }

  try {
    // Extract repository root URL from jsDelivr URL
    const href = window.location.href.split('?')[0].split('#')[0];
    const baseUrl = href.substring(0, href.lastIndexOf('/') + 1);

    status.textContent = 'Streaming Godly OS distribution bundle...';

    // Fetch the production HTML bundle from jsDelivr dist/index.html
    const res = await fetch(baseUrl + 'dist/index.html', { cache: 'no-cache' });
    if (res.ok) {
      let html = await res.text();
      const baseHref = baseUrl + 'dist/';
      const baseTag = '<base href="' + baseHref + '">';

      if (html.includes('<head>')) {
        html = html.replace('<head>', '<head>' + baseTag);
      } else {
        html = baseTag + html;
      }

      frame.onload = () => {
        setTimeout(dismissSplash, 600);
      };

      frame.srcdoc = html;
      return;
    }
  } catch (err) {
    console.warn('Direct jsDelivr fetch failed:', err);
  }

  // Fallback: Connect directly to GitHub Pages mirror
  status.textContent = 'Connecting to GitHub Pages mirror...';
  frame.onload = () => {
    setTimeout(dismissSplash, 600);
  };
  frame.src = 'https://donoela.github.io/Godly-OS-Workspac---Github/';
})();
